use super::*;
use semio_framework_os_kernel::{ArtifactSqliteSnapshot,sqlite_snapshot::*};
fn fixture()->SemioModelSnapshot{let f:serde_json::Value=serde_json::from_str(include_str!("../../🧫️fixtures/🪶️sqlite/🔣️.json")).unwrap();SemioModelSnapshot{schema:f["schema"].as_str().unwrap().into(),spatial:[SpatialKind::Site,SpatialKind::Building,SpatialKind::Storey,SpatialKind::Space].into_iter().enumerate().map(|(ordinal,kind)|SpatialNode{id:format!("spatial-{ordinal}"),kind,name:format!("Spatial {ordinal}"),parent_id:if ordinal==0{None}else{Some(format!("spatial-{}",ordinal-1))},placement:SemioTransform::identity()}).collect(),elements:[ElementClass::Wall,ElementClass::Slab,ElementClass::Column,ElementClass::Beam,ElementClass::Door,ElementClass::Window,ElementClass::Roof,ElementClass::Stair,ElementClass::Furniture,ElementClass::Other{name:f["otherClassName"].as_str().unwrap().into()}].into_iter().enumerate().map(|(ordinal,class)|SemioModelElement{id:format!("element-{ordinal}"),class,placement:SemioTransform::identity(),geometry:match ordinal%3{0=>GeometryRef::None,1=>GeometryRef::Brep{brep_id:f["externalGeometryId"].as_str().unwrap().into()},_=>GeometryRef::Mesh{mesh_id:f["externalGeometryId"].as_str().unwrap().into()}},spatial_id:if ordinal%2==0{Some("spatial-3".into())}else{None},psets:vec![PropertySet{name:"Pset typed".into(),properties:vec![Property{key:"same".into(),value:PsetValue::Text{value:f["propertyText"].as_str().unwrap().into()}},Property{key:"same".into(),value:PsetValue::Number{value:f["propertyNumber"].as_f64().unwrap()}},Property{key:"boolean".into(),value:PsetValue::Boolean{value:ordinal%2==0}}]}]}).collect(),relations:[RelationKind::Aggregates,RelationKind::ContainedIn,RelationKind::ConnectsTo,RelationKind::FillsVoid,RelationKind::VoidsElement,RelationKind::Other{label:f["otherRelationLabel"].as_str().unwrap().into()}].into_iter().enumerate().map(|(ordinal,kind)|ModelRelation{id:format!("relation-{ordinal}"),kind,from:"spatial-0".into(),to:format!("element-{ordinal}")}).collect()}}
fn project(value:&SemioModelSnapshot)->SqliteDatabase{value.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap()}
fn restore(db:&SqliteDatabase)->Result<SemioModelSnapshot, semio_framework_value::ValueError>{SemioModelSnapshot::from_sqlite_database(db,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default()))}
#[test]
fn sqlite_snapshot_semio_model_all_enums_spatial_geometry_properties_relationships_and_native_state(){let snapshot=fixture();let bytes=export_sqlite_database(&project(&snapshot),SqliteDatabaseLimits::default(),&mut |_|true).unwrap();let restored=restore(&import_sqlite_database(&bytes,SqliteDatabaseLimits::default(),&mut |_|true).unwrap()).unwrap();assert_eq!(restored,snapshot);assert_eq!(<SemioModelSnapshot as store::ArtifactPack>::encode_pack(&restored),<SemioModelSnapshot as store::ArtifactPack>::encode_pack(&snapshot));assert_eq!(<SemioModelSnapshot as store::ArtifactDsl>::print_dsl(&restored),<SemioModelSnapshot as store::ArtifactDsl>::print_dsl(&snapshot));assert_eq!(restore(&project(&SemioModelSnapshot::default())).unwrap(),SemioModelSnapshot::default());}
#[test]
fn sqlite_snapshot_semio_model_rejects_cycles_dangling_refs_variant_shapes_and_limits(){let original=project(&fixture());for change in 0..5{let mut db=original.clone();match change{0=>db.table_mut("semio_model_spatial").unwrap().rows[0].values[3]=SqliteValue::Integer(4),1=>db.table_mut("semio_model_relation").unwrap().rows[0].values[6]=SqliteValue::Integer(999),2=>db.table_mut("semio_model_element").unwrap().rows[0].values[2]=SqliteValue::Text("unexpected".into()),3=>db.table_mut("semio_model_property").unwrap().rows[0].values[7]=SqliteValue::Integer(1),_=>db.table_mut("semio_model_geometry_reference").unwrap().rows[0].values[2]=SqliteValue::Text("unexpected".into())}assert!(restore(&db).is_err());}let limits=SqliteDatabaseLimits{max_rows:1,max_value_bytes:1,..SqliteDatabaseLimits::default()};assert!(fixture().to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,limits)).is_err());assert!(SemioModelSnapshot::from_sqlite_database(&original,&mut SqliteSnapshotControl::new(&mut |_|true,limits)).is_err());assert!(fixture().to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|false,SqliteDatabaseLimits::default())).is_err());}
#[test]
fn sqlite_snapshot_semio_model_independent_relationship_join_property_edit_and_validator(){use std::io::Write;use std::process::{Command,Stdio};let bytes=export_sqlite_database(&project(&fixture()),SqliteDatabaseLimits::default(),&mut |_|true).unwrap();let script="import{Database}from'bun:sqlite';const db=Database.deserialize(new Uint8Array(await Bun.stdin.arrayBuffer()));if(db.query('PRAGMA integrity_check').get().integrity_check!=='ok'||db.query('PRAGMA foreign_key_check').all().length)throw Error('integrity');const r=db.query('SELECT s.native_id source,t.native_id target FROM semio_model_relation JOIN semio_model_entity s ON s.id=source_entity_id JOIN semio_model_entity t ON t.id=target_entity_id WHERE semio_model_relation.ordinal=0').get();if(r.source!=='spatial-0'||r.target!=='element-0')throw Error('entities');db.query(\"UPDATE semio_model_property SET text_value='independently edited' WHERE kind='text' AND property_set_id=1\").run();await Bun.write(Bun.stdout,db.serialize());db.close();";let mut child=Command::new("bun").args(["-e",script]).stdin(Stdio::piped()).stdout(Stdio::piped()).stderr(Stdio::piped()).spawn().unwrap();child.stdin.take().unwrap().write_all(&bytes).unwrap();let out=child.wait_with_output().unwrap();assert!(out.status.success(),"{}",String::from_utf8_lossy(&out.stderr));let restored=restore(&import_sqlite_database(&out.stdout,SqliteDatabaseLimits::default(),&mut |_|true).unwrap()).unwrap();let mut expected=fixture();expected.elements[0].psets[0].properties[0].value=PsetValue::Text{value:"independently edited".into()};assert_eq!(restored,expected);assert!(crate::standards::v1::subsets::model::io::semio_model_referential_diagnostics(&restored).is_empty());}

#[test]
fn sqlite_snapshot_semio_model_bare_owner_capability_native_payload_bridge(){let snapshot=fixture();let payload=store::os_io::IoPayload::Binary(<SemioModelSnapshot as store::ArtifactPack>::encode_pack(&snapshot));let codec=store::ArtifactCodec::bare::<SemioModelSnapshot,crate::standards::v1::subsets::model::schema::mutations::SemioModelMutation>("s.stdio.semio.model");let provider=codec.snapshot_sqlite.expect("owner must publish typed SQLite capability");assert_eq!(provider.snapshot_type,Some(std::any::TypeId::of::<SemioModelSnapshot>()));let dialect=store::os_io::ArtifactDialect{artifact_kind:"s.stdio.semio".into(),standard:"v1".into(),subset:"model".into()};let db=(provider.export)("s.stdio.semio.model",&dialect,&payload,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap().value;let bytes=export_sqlite_database(&db,SqliteDatabaseLimits::default(),&mut |_|true).unwrap();let db=import_sqlite_database(&bytes,SqliteDatabaseLimits::default(),&mut |_|true).unwrap();let actual=(provider.import)("s.stdio.semio.model",&dialect,db,SnapshotEncoding::Binary,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap().value;assert_eq!(actual,payload);}

#[test]
fn sqlite_snapshot_semio_model_owned_numeric_bits_independent_sqlite(){use std::io::Write;use std::process::{Command,Stdio};let f:serde_json::Value=serde_json::from_str(include_str!("../../🧫️fixtures/🪶️sqlite/🔣️.json")).unwrap();for(index,bits)in f["float64Bits"].as_array().unwrap().iter().enumerate(){let bits=u64::from_str_radix(bits.as_str().unwrap(),16).unwrap();let bits32=u32::from_str_radix(f["float32Bits"][index].as_str().unwrap(),16).unwrap();let v=f64::from_bits(bits);let _v32=f32::from_bits(bits32);let mut s=fixture();s.spatial[0].placement.translation.x=v;s.elements[0].psets[0].properties[1].value=PsetValue::Number{value:v};let bytes=export_sqlite_database(&project(&s),SqliteDatabaseLimits::default(),&mut |_|true).unwrap();let script="import{Database}from'bun:sqlite';const d=Database.deserialize(new Uint8Array(await Bun.stdin.arrayBuffer()));if(d.query('PRAGMA integrity_check').get().integrity_check!=='ok'||d.query('PRAGMA foreign_key_check').all().length)throw Error('integrity');await Bun.write(Bun.stdout,d.serialize());d.close();";let mut child=Command::new("bun").args(["-e",script]).stdin(Stdio::piped()).stdout(Stdio::piped()).stderr(Stdio::piped()).spawn().unwrap();child.stdin.take().unwrap().write_all(&bytes).unwrap();let out=child.wait_with_output().unwrap();assert!(out.status.success(),"{}",String::from_utf8_lossy(&out.stderr));let r=restore(&import_sqlite_database(&out.stdout,SqliteDatabaseLimits::default(),&mut |_|true).unwrap()).unwrap();assert_eq!((r.spatial[0].placement.translation.x).to_bits(),bits);assert_eq!(<SemioModelSnapshot as store::ArtifactPack>::encode_pack(&r),<SemioModelSnapshot as store::ArtifactPack>::encode_pack(&s));}}

#[test]
fn sqlite_snapshot_semio_model_typed_exact_subset_dialect_and_document_guard(){let f:serde_json::Value=serde_json::from_str(include_str!("../../🧫️fixtures/🪶️sqlite/🔣️.json")).unwrap();let snapshot=fixture();let database=project(&snapshot);let dialect=|v:&serde_json::Value|store::os_io::ArtifactDialect{artifact_kind:v["artifactKind"].as_str().unwrap().into(),standard:v["standard"].as_str().unwrap().into(),subset:v["subset"].as_str().unwrap().into()};let mut callback=|_|true;let mut control=SqliteSnapshotControl::new(&mut callback,SqliteDatabaseLimits::default());assert!(snapshot.validate_sqlite_snapshot_subset(&dialect(&f["sqliteDialect"]),&database,&mut control).unwrap().diagnostics.is_empty());for invalid in f["invalidSqliteDialects"].as_array().unwrap(){assert!(snapshot.validate_sqlite_snapshot_subset(&dialect(invalid),&database,&mut control).is_err());}let mut malformed=database;malformed.table_mut("semio_model_document").unwrap().rows[0].values[1]=SqliteValue::Text("other schema".into());assert!(snapshot.validate_sqlite_snapshot_subset(&dialect(&f["sqliteDialect"]),&malformed,&mut control).is_err());}

#[test]
fn sqlite_snapshot_semio_model_bounded_native_text_binary_admission() {
    let snapshot=fixture();let dialect=store::os_io::ArtifactDialect{artifact_kind:"s.stdio.semio".into(),standard:"v1".into(),subset:"model".into()};
    let provider=<SemioModelSnapshot as store::ArtifactPack>::sqlite_snapshot_codec().unwrap();
    for encoding in [SnapshotEncoding::Binary,SnapshotEncoding::Text]{
        snapshot.preflight_sqlite_snapshot_encoding(encoding,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap();
        let database=snapshot.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap();
        let actual=(provider.import)("Semio native admission",&dialect,database,encoding,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap().value;
        let expected=match encoding{SnapshotEncoding::Text=>store::os_io::IoPayload::Text(<SemioModelSnapshot as store::ArtifactDsl>::print_dsl(&snapshot)),SnapshotEncoding::Binary=>store::os_io::IoPayload::Binary(<SemioModelSnapshot as store::ArtifactPack>::encode_pack(&snapshot))};assert_eq!(actual,expected);
        assert!(snapshot.preflight_sqlite_snapshot_encoding(encoding,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits{max_file_bytes:16,..SqliteDatabaseLimits::default()})).is_err());
        assert!(snapshot.preflight_sqlite_snapshot_encoding(encoding,&mut SqliteSnapshotControl::new(&mut |_|false,SqliteDatabaseLimits::default())).is_err());
    }
    let large= SemioModelSnapshot{schema:"x".repeat(100000),..snapshot};
    assert!(large.preflight_sqlite_snapshot_encoding(SnapshotEncoding::Text,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits{max_value_bytes:4096,..SqliteDatabaseLimits::default()})).is_err());
    assert!(large.preflight_sqlite_snapshot_encoding(SnapshotEncoding::Binary,&mut SqliteSnapshotControl::new(&mut |p|p.phase!=SqliteSnapshotPhase::EncodeNative||p.completed==0,SqliteDatabaseLimits::default())).is_err());
}

#[test]
fn sqlite_snapshot_semio_model_native_text_preserves_ieee_words(){use store::ArtifactDsl;let f:serde_json::Value=serde_json::from_str(include_str!("../../🧫️fixtures/🪶️sqlite/🔣️.json")).unwrap();for word in f["float64Bits"].as_array().unwrap(){let bits=u64::from_str_radix(word.as_str().unwrap(),16).unwrap();let mut value=fixture();value.spatial[0].placement.translation.x=f64::from_bits(bits);let actual=SemioModelSnapshot::parse_dsl(&value.print_dsl()).unwrap();assert_eq!(actual.spatial[0].placement.translation.x.to_bits(),bits);}}
#[test]
fn sqlite_snapshot_semio_model_explicit_controlled_native_owner(){use store::{ArtifactPack,ArtifactDsl};let f:serde_json::Value=serde_json::from_str(include_str!("../../🧫️fixtures/🪶️sqlite/🔣️.json")).unwrap();let expected=fixture();for payload in [store::os_io::IoPayload::Binary(expected.encode_pack()),store::os_io::IoPayload::Text(expected.print_dsl())]{let actual=SemioModelSnapshot::decode_sqlite_snapshot_native(&payload,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap();assert_eq!(actual,expected);assert!(SemioModelSnapshot::decode_sqlite_snapshot_native(&payload,&mut SqliteSnapshotControl::new(&mut |_|false,SqliteDatabaseLimits::default())).is_err());assert!(SemioModelSnapshot::decode_sqlite_snapshot_native(&payload,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits{max_value_bytes:f["nativeAdmission"]["tinyBudgetBytes"].as_u64().unwrap() as usize,..SqliteDatabaseLimits::default()})).is_err());assert!(SemioModelSnapshot::decode_sqlite_snapshot_native(&payload,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits{max_rows:2,..SqliteDatabaseLimits::default()})).is_err());}let count=f["nativeAdmission"]["collectionItems"].as_u64().unwrap() as usize;let canceled=f["nativeAdmission"]["cancelAfter"].as_u64().unwrap() as usize;let value=SemioModelSnapshot{elements:vec![SemioModelElement{id:"element".into(),psets:vec![PropertySet{name:"".into(),properties:(0..count).map(|_|Property{key:"".into(),value:PsetValue::Text{value:"".into()}}).collect()}],..SemioModelElement::default()}],..SemioModelSnapshot::default()};for payload in [store::os_io::IoPayload::Binary(value.encode_pack()),store::os_io::IoPayload::Text(value.print_dsl())]{let mut interior=false;let mut callback=|p:SqliteSnapshotProgress|{if p.phase==SqliteSnapshotPhase::DecodeNative&&p.total==count&&p.completed==canceled{interior=true;false}else{true}};assert!(SemioModelSnapshot::decode_sqlite_snapshot_native(&payload,&mut SqliteSnapshotControl::new(&mut callback,SqliteDatabaseLimits::default())).is_err());assert!(interior);}}

