fn sqlite_snapshot_semio_model_controlled_native_output(){let corpus:serde_json::Value=serde_json::from_str(include_str!("../../🧫️fixtures/🪶️sqlite/🔣️.json")).unwrap();let count=corpus["nativeOutputBytes"].as_u64().unwrap() as usize;let mut snapshot=fixture();if let PsetValue::Text{value}=&mut snapshot.elements[0].psets[0].properties[0].value{*value="x".repeat(count)}else{panic!("fixture property")};crate::standards::v1::subsets::base::schema::snapshot::native_output_tests::assert_output(&snapshot);}
